import{_ as a,o as e,c as t,a3 as c}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"通用篇 - copying & saving","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/02-通用篇-copying-&-saving.md","filePath":"books/chrome-devtools/02-通用篇-copying-&-saving.md","lastUpdated":1781445373000}'),s={name:"books/chrome-devtools/02-通用篇-copying-&-saving.md"};function d(r,o,i,l,p,n){return e(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="通用篇-copying-saving" tabindex="-1">通用篇 - copying &amp; saving <a class="header-anchor" href="#通用篇-copying-saving" aria-label="Permalink to &quot;通用篇 - copying &amp; saving&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>在调试的过程中，我们总要对 <code>Dev Tools</code> 里面的数据进行 <strong>复制</strong> 或者 <strong>保存</strong> 的操作，所以我们来看看，关于这些，有什么小技巧呢？</p><h2 id="_1-copy" tabindex="-1">1. <code>copy(...)</code> <a class="header-anchor" href="#_1-copy" aria-label="Permalink to &quot;1. `copy(...)`&quot;">​</a></h2><p>你可以通过全局的方法 <code>copy()</code> 在 <code>console</code> 里 <code>copy</code> 任何你能拿到的资源，包括我们在后面[第六节]会提到的那些变量。例如 <code>copy($_)</code> 或 <code>copy($0)</code></p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/7/16787442a1444125~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_2-store-as-global-存储为一个全局变量" tabindex="-1">2. <code>Store as global</code> (存储为一个全局变量) <a class="header-anchor" href="#_2-store-as-global-存储为一个全局变量" aria-label="Permalink to &quot;2. `Store as global` (存储为一个全局变量)&quot;">​</a></h2><p>如果你在 <code>console</code> 中打印了一堆数据 (例如你在 <code>App</code> 中计算出来的一个数组) ，然后你想对这些数据做一些额外的操作比如我们刚刚说的 <code>copy</code> (在不影响它原来值的情况下) 。 那就可以将它转换成一个全局变量，只需要 <strong>右击</strong> 它，并选择 “<code>Store as global variable</code>” (保存为全局变量) 选项。</p><p>第一次使用的话，它会创建一个名为 <code>temp1</code> 的变量，第二次创建 <code>temp2</code>，第三次 ... 。通过使用这些变量来操作对应的数据，不用再担心影响到他们原来的值:</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/7/167874429e8b8f73~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_3-保存堆栈信息-stack-trace" tabindex="-1">3.保存堆栈信息( <code>Stack trace</code> ) <a class="header-anchor" href="#_3-保存堆栈信息-stack-trace" aria-label="Permalink to &quot;3.保存堆栈信息( `Stack trace` )&quot;">​</a></h2><p>大多数情况下都不是一个人开发一个项目，而是一个团队协作，那么 <strong>如何准确的描述问题，就成为了沟通的关键</strong> ，这时候 <code>console</code> 打印出来的堆栈跟踪的信息对你和同事来说就起大作用了，可以省去很多沟通成本，所以你可以直接把堆栈跟踪的信息保存为一个文件，而不只是截图发给对方：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/7/16787442c1b6d1f7~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_4-直接copy-html" tabindex="-1">4.直接Copy HTML <a class="header-anchor" href="#_4-直接copy-html" aria-label="Permalink to &quot;4.直接Copy HTML&quot;">​</a></h2><p>几乎所有人都知道，右击或者点击在 <code>HTML</code> 元素边上的省略号 (...) 就可以将它 <code>copy</code> 到剪贴板中</p><p>，但是你不知道的是：古老的<code>[ctrl] + [c]</code>大法依旧可用！</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/7/16787442daaa7199~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',17)])])}const h=a(s,[["render",d]]);export{m as __pageData,h as default};
